// tools/madrid/config.mjs — Phase definitions for the Madrid build (see MADRID.md).
// Every bbox is ETRS89 / UTM zone 30N (EPSG:25830), meters: [xMin, yMin, xMax, yMax].
// Select a phase with MADRID_PHASE=fase1|fase2|fase3 when running the fetch/build tools.

export const CRS = 'EPSG:25830';

// WGS84 corners, converted with pyproj from the UTM boxes (kept here so the Node
// pipeline never needs a projection library; values regenerated by tools/madrid/bbox.py).
export const PHASES = {
  // Phase 1 (this run): centro ~2 km² — Sol, Gran Vía, Callao, Cibeles, Puerta de Alcalá, Plaza Mayor.
  fase1: {
    label: 'Centro (Sol-Gran Vía-Cibeles-Alcalá)',
    utm: [439550, 4473930, 441483, 4474914],
    wgs84: { xMin: -3.712500, yMin: 40.413800, xMax: -3.689800, yMax: 40.422800 },
  },
  // Phase 2 (same pipeline, bigger bbox): the "almendra central" (M-30 wedge south part).
  fase2: {
    label: 'Almendra central',
    utm: [439316, 4473866, 441428, 4474730],
    wgs84: { xMin: -3.715330, yMin: 40.413204, xMax: -3.690357, yMax: 40.421138 },
  },
};

export function getPhase() {
  const name = process.env.MADRID_PHASE || 'fase1';
  const p = PHASES[name];
  if (!p) throw new Error(`Unknown MADRID_PHASE "${name}" (have: ${Object.keys(PHASES).join(', ')})`);
  return { name, ...p };
}
